return [
  { payload: msg.payload[0] }, // Output 1: Physical Field E-Stop Status (Coil 3)
  { payload: msg.payload[1] }, // Output 2: Master Safety Latch Bit (Coil 4)
  { payload: msg.payload[2] }, // Output 3: Motor 1 Running Status (Coil 5)
  { payload: msg.payload[3] }  // Output 4: Motor 2 Running Status (Coil 6)
];

// Extract the value from the Modbus array
let state = msg.payload;
if (Array.isArray(state)) {
    state = state[0];
}

// Translate to text and HP-HMI colors
if (state === true || state === "true" || state === 1) {
    msg.text = "Field Override Active";
    msg.color = "#3399ff"; // Industrial Blue
} else {
    msg.text = "Field Standby";
    msg.color = "#555555"; // Muted Grey
}

return msg;

// Extract the first 16-bit integer from the incoming Modbus payload array
let rawInteger = msg.payload[0];

// Reverse the x100 integer scaling applied by your remote RTU
msg.payload = rawInteger / 100;

msg.topic = "Temperature";

// Pass the scaled floating-point temperature to the HMI dashboard
return msg;

let rawSpeed = msg.payload[0];

// Convert Unsigned 16-bit (UInt16) to Signed 16-bit (Int16)
if (rawSpeed > 32767) {
    rawSpeed = rawSpeed - 65536;
}

// Take the absolute value so it always displays a positive number
let displaySpeed = Math.abs(rawSpeed);

let running = flow.get('motor1Running') || false;
let statusColor = running ? "#2E8B57" : "#808080";
let dirLabel = flow.get('motor1Dir') ? " REV" : " FWD";

msg.payload = displaySpeed + " RPM" + dirLabel;
msg.color = statusColor;
return msg;

let rawSpeed = msg.payload[0];

// Convert Unsigned 16-bit (UInt16) to Signed 16-bit (Int16)
if (rawSpeed > 32767) {
    rawSpeed = rawSpeed - 65536;
}

// Take the absolute value so it always displays a positive number
let displaySpeed = Math.abs(rawSpeed);

let running = flow.get('motor2Running') || false;
let statusColor = running ? "#2E8B57" : "#808080";
let dirLabel = flow.get('motor2Dir') ? " REV" : " FWD";

msg.payload = displaySpeed + " RPM" + dirLabel;
msg.color = statusColor;
return msg;

// Capture the scaled float temperature directly from the input wire
let scaledTemperature = msg.payload; 

// Construct the official Apache IoTDB REST v1 payload block
msg.payload = {
    "deviceId": "root.scada_mini_lab.field_sensors",
    "isAligned": false, // Tells IoTDB this is a standard independent timeseries
    "timestamps": [ Date.now() ],
    "measurements": [ "temperature" ],
    "dataTypes": [ "FLOAT" ],
    "values": [ [ scaledTemperature ] ]
};

// Map standard Authorization credentials
msg.headers = {
    "Authorization": "Basic cm9vdDpyb290", // Base64 signature for root:root
    "Content-Type": "application/json"
};

return msg;

// Capture new selection from dropdown OR recall saved active range
let range = msg.payload;

if (typeof range !== 'string' || (!range.endsWith('m') && !range.endsWith('h'))) {
    range = flow.get('selectedTimeRange') || "15m";
} else {
    flow.set('selectedTimeRange', range);
}

let timeOffsetMs = 15 * 60 * 1000;
let rowLimit = 1000;
let rangeLabel = "15M";

if (range === "1h") {
    timeOffsetMs = 60 * 60 * 1000;
    rowLimit = 3600;
    rangeLabel = "1H";
} else if (range === "6h") {
    timeOffsetMs = 6 * 60 * 60 * 1000;
    rowLimit = 5000;
    rangeLabel = "6H";
} else if (range === "24h") {
    timeOffsetMs = 24 * 60 * 60 * 1000;
    rowLimit = 5000;
    rangeLabel = "24H";
}

let startTime = Date.now() - timeOffsetMs;
msg.startTime = startTime;
msg.rangeLabel = rangeLabel;

msg.payload = {
    "sql": `SELECT temperature FROM root.scada_mini_lab.field_sensors WHERE time >= ${startTime} ORDER BY time DESC LIMIT ${rowLimit}`
};

return msg;

let timestamps = msg.payload.timestamps || [];
// Flatten IoTDB's nested array response structure
let rawValues = msg.payload.values ? msg.payload.values.flat(Infinity) : [];

let chartData = [];

for (let i = 0; i < timestamps.length; i++) {
    let val = parseFloat(rawValues[i]);

    // Filter out offline zeroes (0.00) and sensor power-on error spikes (85.00+)
    if (!isNaN(val) && val > 0 && val < 85) {
        chartData.push({
            x: timestamps[i],
            y: parseFloat(val.toFixed(2))
        });
    }
}

// Re-order chronologically (oldest to newest)
chartData.reverse();

// Anchor time range start point if needed
if (msg.startTime && chartData.length > 0) {
    if (chartData[0].x > msg.startTime + 5000) {
        chartData.unshift({
            x: msg.startTime,
            y: chartData[0].y
        });
    }
}

let clearMsg = { payload: [] };
let updateMsg = {
    payload: [{
        "series": ["Temperature"],
        "data": [chartData],
        "labels": ["Temperature"]
    }]
};

return [[ clearMsg, updateMsg ]];

let avgVal = "--";
let maxVal = "--";
let minVal = "--";
let rangeLabel = msg.rangeLabel || "RANGE";

if (msg.payload && msg.payload.values && msg.payload.values.length > 0) {
    let numbers = [];

    // Flatten IoTDB's nested column array
    let flatValues = msg.payload.values.flat(Infinity);

    for (let i = 0; i < flatValues.length; i++) {
        let val = parseFloat(flatValues[i]);

        // Filter out offline zeroes (0.00) and sensor power-on error spikes (85.00+)
        if (!isNaN(val) && val > 0 && val < 85) {
            numbers.push(val);
        }
    }

    // Compute true operational metrics
    if (numbers.length > 0) {
        let sum = numbers.reduce((acc, curr) => acc + curr, 0);
        let avg = sum / numbers.length;
        let max = Math.max(...numbers);
        let min = Math.min(...numbers);

        avgVal = avg.toFixed(2);
        maxVal = max.toFixed(2);
        minVal = min.toFixed(2);
    }
}

msg.payload = {
    avg: avgVal,
    max: maxVal,
    min: minVal,
    label: rangeLabel
};

return msg;

// Extract floating-point temperature reading
let temp = parseFloat(msg.payload);

let statusState = "NOMINAL";
let statusText = "NOMINAL PROCESS TEMPERATURE";
let bgColor = "#2e8b57"; // Muted Industrial Green
let textColor = "#ffffff";
let isFlashing = false;

// Evaluate temperature thresholds according to PLC thermal curve
if (isNaN(temp) || temp <= 0 || temp >= 200) {
    statusState = "SENSOR FAULT";
    statusText = "SENSOR SIGNAL DISCONNECTED / FAULT";
    bgColor = "#808080"; // Grey
} else if (temp >= 60.0) {
    statusState = "CRITICAL ALARM";
    statusText = "HIGH TEMP ALARM: MOTOR 2 MAX SPEED";
    bgColor = "#dc3545"; // Warning Red
    isFlashing = true;
} else if (temp >= 30.0) {
    statusState = "WARNING";
    statusText = "THERMAL RAMP ACTIVE: MOTOR 2 ACCELERATING";
    bgColor = "#e0a72f"; // Amber / Yellow
}

msg.payload = {
    temp: temp.toFixed(2),
    state: statusState,
    text: statusText,
    bgColor: bgColor,
    textColor: textColor,
    flash: isFlashing
};

return msg;

// Check HTTP response code from Apache IoTDB REST API
// statusCode 200 or 202 = Success
let statusCode = msg.statusCode || (msg.res ? msg.res.statusCode : null);

if (statusCode === 200 || statusCode === 202) {
    // Database ingestion is working normally
    msg.payload = true;
    msg.topic = "Historian Logging OK";
} else {
    // Database connection failed, endpoint unreachable, or internal error
    msg.payload = false;
    msg.topic = "Database Failure";
}

return msg;
